describe('Modal Form Submission with Success Feedback', () => {
  beforeEach(() => {
    cy.visit('/form-modal');
  });

  it('should submit form inside modal and display success feedback', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Fill form fields
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="message-textarea"]').type('This is a test message');

    // Verify form is visible and fields are filled
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john.doe@example.com');
    cy.get('[data-testid="message-textarea"]').should('have.value', 'This is a test message');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API response
    cy.wait('@formSubmit');

    // Verify success feedback is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify modal is closed
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should handle form submission failure and display error feedback', () => {
    // Intercept the API call with a failure response
    cy.intercept('POST', '/api/form-submit', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('formSubmitFailure');

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('be.visible');

    // Fill form fields
    cy.get('[data-testid="name-input"]').type('Jane Smith');
    cy.get('[data-testid="email-input"]').type('jane.smith@example.com');
    cy.get('[data-testid="message-textarea"]').type('Please process my request');

    // Submit form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API response
    cy.wait('@formSubmitFailure');

    // Verify error feedback is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to submit form');

    // Verify modal is still open
    cy.get('[data-testid="modal-container"]').should('be.visible');
  });
});
